/* ==UserStyle==
@name         Light Navy Blue on Create-Style Page
@namespace    yourname.userstyles
@version      1.0
@description  Light navy blue theme for userstyles.org “create style” page
@match        https://userstyles.org/create-style*
==/UserStyle== */

:root {
}

body, html {
    background: var(--light-navy) !important;
    color: var(--text-color) !important;
}

a {
    color: #cbd9ff !important;
}

input, textarea, select, button {
    background: #1f2f55 !important;
    color: var(--text-color) !important;
    border: 1px solid #cbd9ff !important;
}

div, section, article {
    background: transparent !important;
    color: var(--text-color) !important;
}

* {
    color: var(--text-color) !important;
}
